"""index.html's offline provider list is the registry's, generated, not kept by hand.

`PROV_FALLBACK` is what the client uses when `data/providers.json` cannot be read, and
`fetchVenueLists()` asks for `data/venues-{id}.json` for whichever list is in force. So a
provider missing from the fallback does not merely lose its label: it loses its venues
from the picker, the health line and the chain palette. Kept by hand it fell 31 providers
and 38 of 86 venues behind the registry by 2026-09-14, which is what this file exists to
stop happening again.

The block is generated by `scripts/build_providers.py --sync-index`. This is the gate
rather than a non-zero exit from that script, because `biorex.yml` runs it ungated before
it fetches anything and a data run must not fail over a documentation problem.
"""
import pathlib
import re
import unittest

import _ctx                                                # noqa: F401
import build_providers as bp
import registry

ROOT = _ctx.ROOT
HTML = (ROOT / "index.html").read_text(encoding="utf-8")


def block():
    """The committed fallback entries, between the markers."""
    return HTML.split(bp.START)[1].split(bp.END)[0]


def ids(text):
    return re.findall(r"id:'([A-Za-z0-9_-]+)'", text)


class FallbackIsGeneratedTest(unittest.TestCase):
    def test_the_committed_block_is_what_the_registry_generates(self):
        """The drift gate. `--sync-index` rewrites it; this fails until someone has."""
        self.assertEqual(bp.index_block(HTML, bp.fallback_body()), HTML,
                         "index.html's PROV_FALLBACK is stale: run "
                         "`python3 scripts/build_providers.py --sync-index` and bump sw.js")

    def test_every_registry_provider_is_in_the_fallback(self):
        """Stated as the set rather than as a count, so it cannot pass by coincidence."""
        self.assertEqual(ids(block()), [p["id"] for p in registry.PROVIDERS])

    def test_the_fallback_carries_what_the_client_reads_off_a_provider(self):
        """applyProviders() reads label, host, accent and book. A missing accent leaves a
        chain with no rule in the palette, which is the one signal a combined city view
        has besides the venue name."""
        entries = [ln for ln in block().split("\n") if "id:" in ln]
        self.assertEqual(len(entries), len(registry.PROVIDERS))
        for line in entries:
            with self.subTest(entry=line.strip()[:40]):
                for key in ("id:", "label:", "host:", "accent:", "book:"):
                    self.assertIn(key, line)
                self.assertRegex(line, r"accent:'#[0-9A-Fa-f]{6}'")

    def test_the_generator_is_idempotent(self):
        """Rebuilding a file it just wrote must change nothing. Comparing the extracted
        region instead of the file got this wrong and reported every run as stale."""
        once = bp.index_block(HTML, bp.fallback_body())
        self.assertEqual(bp.index_block(once, bp.fallback_body()), once)


class FallbackEscapingTest(unittest.TestCase):
    """The registry is this repo's own file, so this is about the generator staying
    honest rather than about hostile input."""

    def entry(self, **over):
        p = {"id": "x", "label": "L", "host": "h.fi", "accent": "#001122", "book": "buy"}
        p.update(over)
        return bp.fallback_body([p])

    def test_an_apostrophe_in_a_label_does_not_end_the_literal(self):
        self.assertIn(r"label:'Don\'t Look Back',", self.entry(label="Don't Look Back"))

    def test_a_closing_script_tag_is_broken_up(self):
        """A literal `</script>` ends the element whatever its type attribute says, the
        rule ld_json() in build_pages.py already follows."""
        out = self.entry(label="a</script>b")
        self.assertNotIn("</script>", out)
        self.assertIn(r"<\/script>", out)

    def test_a_backslash_is_escaped(self):
        self.assertIn(r"label:'a\\b',", self.entry(label=r"a\b"))


class WhyItMattersTest(unittest.TestCase):
    """Pins the client behaviour that turns a short fallback into missing venues. If the
    client stops deriving its venue requests from PROVIDERS, this file is measuring
    something that no longer matters and should be revisited rather than deleted."""

    def test_the_venue_files_are_requested_for_whatever_provider_list_is_in_force(self):
        fn = HTML[HTML.index("async function fetchVenueLists("):]
        fn = fn[:fn.index("\n  }")]
        self.assertIn("PROVIDERS.map(p => p.id)", fn)
        self.assertIn("data/venues-${prov}.json", fn)

    def test_a_failed_providers_fetch_falls_back_rather_than_failing(self):
        self.assertIn("catch(_){ applyProviders(null); }", HTML)
        self.assertIn("PROVIDERS = (Array.isArray(list) && list.length) ? list : PROV_FALLBACK;",
                      HTML)


if __name__ == "__main__":
    unittest.main()
